TEXT ·mulAdxE2(SB), $432-24
	NO_LOCAL_POINTERS
	CMPB ·supportAdx(SB), $1
	JNE  l4

	// 𝔽p2 = 𝔽p[u]/(u² - (-1)), lazy reduction:
	// t0 = x.A0 * y.A0                     (unreduced)
	// t1 = x.A1 * y.A1                     (unreduced)
	// t2 = (x.A0 + x.A1) * (y.A0 + y.A1)   (unreduced)
	// z.A1 = REDC(t2 - t0 - t1)
	// z.A0 = REDC(t0 - t1 + p²)

#define MACC(in0, in1, in2) \
	ADCXQ in0, in1     \
	MULXQ in2, AX, in0 \
	ADOXQ AX, in1      \

#define FOLD_CARRIES() \
	MOVQ  $0, AX \
	ADCXQ AX, BP \
	ADOXQ AX, BP \

	MOVQ $const_q0, AX
	MOVQ AX, s0-8(SP)
	MOVQ $const_q1, AX
	MOVQ AX, s1-16(SP)
	MOVQ $const_q2, AX
	MOVQ AX, s2-24(SP)
	MOVQ $const_q3, AX
	MOVQ AX, s3-32(SP)
	MOVQ $const_q4, AX
	MOVQ AX, s4-40(SP)
	MOVQ $const_q5, AX
	MOVQ AX, s5-48(SP)

	// aSum = x.A0 + x.A1 (no reduction)
	MOVQ x+8(FP), AX
	MOVQ 0(AX), R13
	MOVQ 8(AX), R14
	MOVQ 16(AX), CX
	MOVQ 24(AX), BX
	MOVQ 32(AX), SI
	MOVQ 40(AX), DI
	ADDQ 48(AX), R13
	ADCQ 56(AX), R14
	ADCQ 64(AX), CX
	ADCQ 72(AX), BX
	ADCQ 80(AX), SI
	ADCQ 88(AX), DI
	MOVQ R13, s42-344(SP)
	MOVQ R14, s43-352(SP)
	MOVQ CX, s44-360(SP)
	MOVQ BX, s45-368(SP)
	MOVQ SI, s46-376(SP)
	MOVQ DI, s47-384(SP)

	// bSum = y.A0 + y.A1 (no reduction)
	MOVQ y+16(FP), AX
	MOVQ 0(AX), R13
	MOVQ 8(AX), R14
	MOVQ 16(AX), CX
	MOVQ 24(AX), BX
	MOVQ 32(AX), SI
	MOVQ 40(AX), DI
	ADDQ 48(AX), R13
	ADCQ 56(AX), R14
	ADCQ 64(AX), CX
	ADCQ 72(AX), BX
	ADCQ 80(AX), SI
	ADCQ 88(AX), DI
	MOVQ R13, s48-392(SP)
	MOVQ R14, s49-400(SP)
	MOVQ CX, s50-408(SP)
	MOVQ BX, s51-416(SP)
	MOVQ SI, s52-424(SP)
	MOVQ DI, s53-432(SP)
	MOVQ x+8(FP), R8
	MOVQ y+16(FP), R9

	// t0 = x.A0 * y.A0 (unreduced)
	MOVQ  0(R9), DX
	MULXQ 0(R8), R10, R11
	MULXQ 8(R8), AX, R12
	ADDQ  AX, R11
	MULXQ 16(R8), AX, R15
	ADCQ  AX, R12
	MULXQ 24(R8), AX, R13
	ADCQ  AX, R15
	MULXQ 32(R8), AX, R14
	ADCQ  AX, R13
	MULXQ 40(R8), AX, CX
	ADCQ  AX, R14
	ADCQ  $0, CX
	MOVQ  R10, s6-56(SP)
	MOVQ  8(R9), DX
	XORQ  R10, R10
	MULXQ 0(R8), AX, BP
	ADOXQ AX, R11
	MACC(BP, R12, 8(R8))
	MACC(BP, R15, 16(R8))
	MACC(BP, R13, 24(R8))
	MACC(BP, R14, 32(R8))
	MACC(BP, CX, 40(R8))
	FOLD_CARRIES()
	MOVQ  BP, R10
	MOVQ  R11, s7-64(SP)
	MOVQ  16(R9), DX
	XORQ  R11, R11
	MULXQ 0(R8), AX, BP
	ADOXQ AX, R12
	MACC(BP, R15, 8(R8))
	MACC(BP, R13, 16(R8))
	MACC(BP, R14, 24(R8))
	MACC(BP, CX, 32(R8))
	MACC(BP, R10, 40(R8))
	FOLD_CARRIES()
	MOVQ  BP, R11
	MOVQ  R12, s8-72(SP)
	MOVQ  24(R9), DX
	XORQ  R12, R12
	MULXQ 0(R8), AX, BP
	ADOXQ AX, R15
	MACC(BP, R13, 8(R8))
	MACC(BP, R14, 16(R8))
	MACC(BP, CX, 24(R8))
	MACC(BP, R10, 32(R8))
	MACC(BP, R11, 40(R8))
	FOLD_CARRIES()
	MOVQ  BP, R12
