	MULXQ 48(R8), BX, SI
	MULXQ 56(R8), AX, DI
	ADDQ  AX, SI
	MULXQ 64(R8), AX, CX
	ADCQ  AX, DI
	MULXQ 72(R8), AX, R10
	ADCQ  AX, CX
	MULXQ 80(R8), AX, R11
	ADCQ  AX, R10
	MULXQ 88(R8), AX, R12
	ADCQ  AX, R11
	ADCQ  $0, R12
	MOVQ  BX, s18-152(SP)
	MOVQ  56(R9), DX
	XORQ  BX, BX
	MULXQ 48(R8), AX, BP
	ADOXQ AX, SI
	MACC(BP, DI, 56(R8))
	MACC(BP, CX, 64(R8))
	MACC(BP, R10, 72(R8))
	MACC(BP, R11, 80(R8))
	MACC(BP, R12, 88(R8))
	FOLD_CARRIES()
	MOVQ  BP, BX
	MOVQ  SI, s19-160(SP)
	MOVQ  64(R9), DX
	XORQ  SI, SI
	MULXQ 48(R8), AX, BP
	ADOXQ AX, DI
	MACC(BP, CX, 56(R8))
	MACC(BP, R10, 64(R8))
	MACC(BP, R11, 72(R8))
	MACC(BP, R12, 80(R8))
	MACC(BP, BX, 88(R8))
	FOLD_CARRIES()
	MOVQ  BP, SI
	MOVQ  DI, s20-168(SP)
	MOVQ  72(R9), DX
	XORQ  DI, DI
	MULXQ 48(R8), AX, BP
	ADOXQ AX, CX
	MACC(BP, R10, 56(R8))
