	MACC(BP, SI, 88(R8))
	FOLD_CARRIES()
	MOVQ  BP, DI
	MOVQ  CX, s21-176(SP)
	MOVQ  80(R9), DX
	XORQ  CX, CX
	MULXQ 48(R8), AX, BP
	ADOXQ AX, R10
	MACC(BP, R11, 56(R8))
	MACC(BP, R12, 64(R8))
	MACC(BP, BX, 72(R8))
	MACC(BP, SI, 80(R8))
	MACC(BP, DI, 88(R8))
