	MOVQ  BP, CX
	MOVQ  R10, s22-184(SP)
	MOVQ  88(R9), DX
	XORQ  R10, R10
	MULXQ 48(R8), AX, BP
	ADOXQ AX, R11
	MACC(BP, R12, 56(R8))
	MACC(BP, BX, 64(R8))
	MACC(BP, SI, 72(R8))
	MACC(BP, DI, 80(R8))
	MACC(BP, CX, 88(R8))
	FOLD_CARRIES()
	MOVQ  BP, R10
	MOVQ  R11, s23-192(SP)
