	// x.A1[0] -> R13
	// x.A1[1] -> R14
	// x.A1[2] -> CX
	// x.A1[3] -> BX
	// x.A1[4] -> SI
	// x.A1[5] -> DI
	MOVQ 48(AX), R13
	MOVQ 56(AX), R14
	MOVQ 64(AX), CX
	MOVQ 72(AX), BX
	MOVQ 80(AX), SI
	MOVQ 88(AX), DI
	MOVQ res+0(FP), DX
	MOVQ R8, 48(DX)
	MOVQ R9, 56(DX)
	MOVQ R10, 64(DX)
	MOVQ R11, 72(DX)
	MOVQ R12, 80(DX)
	MOVQ R15, 88(DX)
	MOVQ R13, R8
	MOVQ R14, R9
	MOVQ CX, R10
	MOVQ BX, R11
	MOVQ SI, R12
	MOVQ DI, R15

	// Add(&x.A0, &x.A1)
	ADDQ 0(AX), R13
	ADCQ 8(AX), R14
	ADCQ 16(AX), CX
	ADCQ 24(AX), BX
	ADCQ 32(AX), SI
	ADCQ 40(AX), DI
	MOVQ R13, s6-56(SP)
	MOVQ R14, s7-64(SP)
	MOVQ CX, s8-72(SP)
	MOVQ BX, s9-80(SP)
	MOVQ SI, s10-88(SP)
	MOVQ DI, s11-96(SP)
	XORQ DX, DX

	// Sub(&x.A0, &x.A1)
	MOVQ    0(AX), R13
	MOVQ    8(AX), R14
	MOVQ    16(AX), CX
	MOVQ    24(AX), BX
	MOVQ    32(AX), SI
	MOVQ    40(AX), DI
	SUBQ    R8, R13
	SBBQ    R9, R14
	SBBQ    R10, CX
	SBBQ    R11, BX
	SBBQ    R12, SI
	SBBQ    R15, DI
	MOVQ    $0xb9feffffffffaaab, R8
	MOVQ    $0x1eabfffeb153ffff, R9
	MOVQ    $0x6730d2a0f6b0f624, R10
	MOVQ    $0x64774b84f38512bf, R11
	MOVQ    $0x4b1ba7b6434bacd7, R12
	MOVQ    $0x1a0111ea397fe69a, R15
	CMOVQCC DX, R8
	CMOVQCC DX, R9
	CMOVQCC DX, R10
	CMOVQCC DX, R11
	CMOVQCC DX, R12
	CMOVQCC DX, R15
	ADDQ    R8, R13
	ADCQ    R9, R14
	ADCQ    R10, CX
	ADCQ    R11, BX
	ADCQ    R12, SI
	ADCQ    R15, DI

	// A -> BP
	// t[0] -> R8
	// t[1] -> R9
	// t[2] -> R10
	// t[3] -> R11
	// t[4] -> R12
	// t[5] -> R15
	// mul body
	MOVQ s6-56(SP), DX
	MUL_WORD_0()
	MOVQ s7-64(SP), DX
	MUL_WORD_N()
	MOVQ s8-72(SP), DX
	MUL_WORD_N()
	MOVQ s9-80(SP), DX
	MUL_WORD_N()
	MOVQ s10-88(SP), DX
	MUL_WORD_N()
	MOVQ s11-96(SP), DX
	MUL_WORD_N()

	// reduce element(R8,R9,R10,R11,R12,R15) using temp registers (R13,R14,CX,BX,SI,DI)
	REDUCE(R8,R9,R10,R11,R12,R15,R13,R14,CX,BX,SI,DI,s0-8(SP),s1-16(SP),s2-24(SP),s3-32(SP),s4-40(SP),s5-48(SP))

	MOVQ res+0(FP), AX
	MOVQ R8, 0(AX)
	MOVQ R9, 8(AX)
	MOVQ R10, 16(AX)
	MOVQ R11, 24(AX)
	MOVQ R12, 32(AX)
	MOVQ R15, 40(AX)
	RET

l5:
	MOVQ res+0(FP), AX
	MOVQ AX, (SP)
	MOVQ x+8(FP), AX
	MOVQ AX, 8(SP)
	CALL ·squareGenericE2(SB)
	RET
